<?php
/** Bounded arithmetic parser; deliberately does not execute PHP/SQL/JavaScript. */
final class StudioFormula {
 private array $tokens=[];private int $i=0;private const POWERS=['=='=>1,'!='=>1,'>'=>1,'<'=>1,'>='=>1,'<='=>1,'+'=>2,'-'=>2,'*'=>3,'/'=>3,'%'=>3,'^'=>4];
 public function __construct(string $source){if(strlen($source)>500)throw new InvalidArgumentException('Formula exceeds 500 characters');$at=0;while($at<strlen($source)){if(!preg_match('/\G\s*(\d+(?:\.\d+)?|[A-Za-z][A-Za-z0-9_]*|>=|<=|==|!=|[+\-*\/%^(),<>])/',$source,$m,0,$at)){if(trim(substr($source,$at))==='')break;throw new InvalidArgumentException('Invalid formula character');}$this->tokens[]=$m[1];$at+=strlen($m[0]);if(count($this->tokens)>256)throw new InvalidArgumentException('Formula too complex');}}
 public function parse():array{$tree=$this->expr();if($this->i!==count($this->tokens))throw new InvalidArgumentException('Unexpected token');return $tree;}
 private function expr(int $min=0,int $depth=0):array{if($depth>24)throw new InvalidArgumentException('Formula too deep');$t=$this->tokens[$this->i++]??'';if($t==='')throw new InvalidArgumentException('Incomplete formula');
 if($t==='+'||$t==='-')$left=['kind'=>'op','name'=>$t==='-'?'neg':'pos','args'=>[$this->expr(4,$depth+1)]];
 elseif($t==='('){$left=$this->expr(0,$depth+1);if(($this->tokens[$this->i++]??'')!==')')throw new InvalidArgumentException('Missing closing bracket');}
 elseif(ctype_digit($t[0]))$left=['kind'=>'number','value'=>(float)$t];
 elseif(ctype_alpha($t[0])){if(($this->tokens[$this->i]??'')==='('){$this->i++;$name=strtoupper($t);if(!in_array($name,['MIN','MAX','ABS','ROUND','FLOOR','CEIL','IF'],true))throw new InvalidArgumentException('Unknown function');$args=[];if(($this->tokens[$this->i]??'')!==')'){do{$args[]=$this->expr(0,$depth+1);if(count($args)>20)throw new InvalidArgumentException('Too many arguments');if(($this->tokens[$this->i]??'')!==',')break;$this->i++;}while(true);}if(($this->tokens[$this->i++]??'')!==')')throw new InvalidArgumentException('Missing closing bracket');$n=count($args);if(($name==='IF'&&$n!==3)||($name==='ROUND'&&($n<1||$n>2))||(in_array($name,['ABS','FLOOR','CEIL'])&&$n!==1)||(in_array($name,['MIN','MAX'])&&$n<1))throw new InvalidArgumentException('Invalid argument count');$left=['kind'=>'call','name'=>$name,'args'=>$args];}else $left=['kind'=>'field','name'=>$t];}
 else throw new InvalidArgumentException('Invalid formula');while($this->i<count($this->tokens)&&(self::POWERS[$this->tokens[$this->i]]??-1)>=$min){$op=$this->tokens[$this->i++];$left=['kind'=>'op','name'=>$op,'args'=>[$left,$this->expr(self::POWERS[$op]+($op==='^'?0:1),$depth+1)]];}return $left;}
 public static function refs(array $tree):array{if($tree['kind']==='field')return [$tree['name']];if($tree['kind']==='number')return [];return array_values(array_unique(array_merge(...array_map([self::class,'refs'],$tree['args']))));}
 private static function bound(float $v):float{if(!is_finite($v)||abs($v)>1e15)throw new InvalidArgumentException('Calculation exceeds safe limits');return $v;}
 public static function value(array $tree,array $values):float{if($tree['kind']==='number')return self::bound($tree['value']);if($tree['kind']==='field'){if(!array_key_exists($tree['name'],$values))throw new InvalidArgumentException('Missing numeric field');return self::bound($values[$tree['name']]);}$name=$tree['name'];if($tree['kind']==='call'&&$name==='IF')return self::value($tree['args'][self::value($tree['args'][0],$values)!=0?1:2],$values);$x=array_map(fn($v)=>self::value($v,$values),$tree['args']);$a=$x[0];$b=$x[1]??null;
 if(in_array($name,['/','%'])&&$b==0)throw new InvalidArgumentException('Division by zero');if($name==='^'&&abs($b)>12)throw new InvalidArgumentException('Exponent exceeds limit');if($name==='ROUND'&&($b??2)!==floor($b??2)||$name==='ROUND'&&(($b??2)<0||($b??2)>6))throw new InvalidArgumentException('Precision must be 0–6');
 $v=match($name){'MIN'=>min($x),'MAX'=>max($x),'ABS'=>abs($a),'ROUND'=>round($a,(int)($b??2),PHP_ROUND_HALF_UP),'FLOOR'=>floor($a),'CEIL'=>ceil($a),'neg'=>-$a,'pos'=>$a,'+'=>$a+$b,'-'=>$a-$b,'*'=>$a*$b,'/'=>$a/$b,'%'=>fmod($a,$b),'^'=>pow($a,$b),'>'=>(float)($a>$b),'<'=>(float)($a<$b),'>='=>(float)($a>=$b),'<='=>(float)($a<=$b),'=='=>(float)($a===$b),'!='=>(float)($a!==$b),default=>throw new InvalidArgumentException('Unknown operation')};return self::bound((float)$v);}
}
function studioTrees(array $fields):array{$trees=[];$numeric=[];foreach($fields as $f)if(in_array($f['type'],['number','formula']))$numeric[$f['key']]=true;foreach($fields as $f)if($f['type']==='formula'){$trees[$f['key']]=(new StudioFormula($f['formula']))->parse();foreach(StudioFormula::refs($trees[$f['key']]) as $key)if(!isset($numeric[$key]))throw new InvalidArgumentException('Unknown numeric field '.$key);}$visiting=[];$done=[];$visit=function($key)use(&$visit,&$visiting,&$done,$trees){if(isset($visiting[$key]))throw new InvalidArgumentException('Circular formula');if(isset($done[$key]))return;$visiting[$key]=true;foreach(StudioFormula::refs($trees[$key]) as $dep)if(isset($trees[$dep]))$visit($dep);unset($visiting[$key]);$done[$key]=true;};foreach(array_keys($trees) as $key)$visit($key);return $trees;}
function studioCalculate(array $fields,array $input):array{$trees=studioTrees($fields);$out=[];$numbers=[];$keys=array_column($fields,'key');if(array_diff(array_keys($input),$keys))throw new InvalidArgumentException('Unknown form field');foreach($fields as $f){if($f['type']==='formula')continue;$v=$input[$f['key']]??($f['type']==='number'?0:'');if($f['required']&&(!array_key_exists($f['key'],$input)||$v===''||$v===null))throw new InvalidArgumentException('Required: '.$f['key']);if($f['type']==='number'){if((!is_int($v)&&!is_float($v))||!is_finite((float)$v)||abs($v)>1e12)throw new InvalidArgumentException('Invalid number');$numbers[$f['key']]=$v;}else{if(!is_string($v)||mb_strlen($v)>2000)throw new InvalidArgumentException('Invalid text');if($f['type']==='select'&&$v!==''&&!in_array($v,$f['options'],true))throw new InvalidArgumentException('Invalid choice');if($f['type']==='date'&&$v!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v)||!($date=DateTimeImmutable::createFromFormat('!Y-m-d',$v))||$date->format('Y-m-d')!==$v))throw new InvalidArgumentException('Invalid date');}$out[$f['key']]=$v;}
 $defs=array_column($fields,null,'key');$calc=function($key)use(&$calc,&$numbers,&$out,$trees,$defs){if(array_key_exists($key,$numbers))return $numbers[$key];foreach(StudioFormula::refs($trees[$key]) as $dep)if(isset($trees[$dep]))$calc($dep);$v=round(StudioFormula::value($trees[$key],$numbers),$defs[$key]['precision'],PHP_ROUND_HALF_UP);if(abs($v)>1e12)throw new InvalidArgumentException('Result exceeds limit');return $out[$key]=$numbers[$key]=$v;};foreach(array_keys($trees) as $key)$calc($key);return $out;}
